import React, { useRef, useLayoutEffect } from 'react'
import { useFrame } from 'react-three-fiber'
import lerp from 'lerp'

/**
 * Yaw/pitch around local origin (mascot hole centre).
 * Must sit ABOVE non-uniform animation scale, otherwise the spin axis drifts.
 */
export default function InspectOrbit({ inspectRef, children }) {
  const orbitRef = useRef()
  const smooth = useRef({ rotX: 0, rotY: 0 })

  useLayoutEffect(() => {
    if (orbitRef.current) orbitRef.current.rotation.order = 'YXZ'
  }, [])

  useFrame(() => {
    if (!orbitRef.current || !inspectRef?.current) return
    const t = inspectRef.current
    const rot = orbitRef.current.rotation
    if (rot.order !== 'YXZ') rot.order = 'YXZ'

    if (t.snap || t.dragging) {
      smooth.current.rotX = t.enabled ? t.rotX : 0
      smooth.current.rotY = t.enabled ? t.rotY : 0
    } else if (!t.enabled) {
      smooth.current.rotX = lerp(smooth.current.rotX, 0, 0.12)
      smooth.current.rotY = lerp(smooth.current.rotY, 0, 0.12)
    } else {
      smooth.current.rotX = lerp(smooth.current.rotX, t.rotX, 0.18)
      smooth.current.rotY = lerp(smooth.current.rotY, t.rotY, 0.18)
    }

    // Yaw (Y) then pitch (X) — spins on the central vertical axis through the hole.
    rot.y = smooth.current.rotY
    rot.x = smooth.current.rotX
    rot.z = 0
  })

  return <group ref={orbitRef}>{children}</group>
}
